      "description": "현재 페이지 (1부터 시작, 반드시 숫자 타입)"
    },
    "pageSize": {
      "type": "integer",
      "description": "페이지당 항목 수 (200 권장)"
    }
  },
  "required": [
    "userId",
    "mgmtOrgId",
    "asstType",
    "templateNo",
    "rspnMngId"
  ],
  "additionalProperties": true,
  "strict": false
}
